    /// <summary>
    /// CB223_PalletRounding PalletRoundingPolicyLineRefRecId jumpRef
    /// </summary>
    /// <param name="sender">Form sender</param>
    /// <param name="e">FormEventArgs</param>
    [FormEventHandler(formStr(SalesTable), FormEventType::Initialized),
     SuppressBPWarningAttribute('BPParameterNotUsed', 'No use for FormEventArgs')]
    public static void SalesTable_OnInitialized(xFormRun sender, FormEventArgs e)
    {
        FormInt64Control control = sender.design().controlName(formControlStr(SalesTable, METPalletRounding_PalletRoundingPolicyLineRefRecId));
        control.registerOverrideMethod(methodStr(FormInt64Control, jumpRef), methodStr(METSalesTableFrm_Extension, METPalletRoundingPolicyLineRefRecIdJumpRef), sender);
    }
